keyLight.position.set(-4, 9, 6); scene.add(keyLight);
const cameraLamp = new THREE.PointLight(0xffb76a, 1.7, 16, 2);
cameraLamp.position.set(0, 2.8, 7); scene.add(cameraLamp);

function concreteTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 256;
  const ctx = c.getContext('2d'); ctx.fillStyle = '#77766e'; ctx.fillRect(0,0,256,256);
  for(let i=0;i<5200;i++){const x=Math.random()*256,y=Math.random()*256,a=Math.random()*.17;ctx.fillStyle=Math.random()>.5?`rgba(20,25,24,${a})`:`rgba(220,215,196,${a*.55})`;ctx.fillRect(x,y,Math.random()*3+.4,Math.random()*3+.4)}
  ctx.strokeStyle='rgba(25,29,28,.2)';ctx.lineWidth=2;ctx.strokeRect(4,4,248,248);ctx.beginPath();ctx.moveTo(0,126);ctx.lineTo(256,126);ctx.stroke();
  const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(2,2);t.colorSpace=THREE.SRGBColorSpace;return t;
}
function floorTexture() {
  const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');x.fillStyle='#414644';x.fillRect(0,0,256,256);
  for(let i=0;i<1800;i++){x.fillStyle=`rgba(${Math.random()>0.5?'205,193,166':'5,10,10'},${Math.random()*.09})`;x.fillRect(Math.random()*256,Math.random()*256,Math.random()*4+1,Math.random()*4+1)}
  x.strokeStyle='rgba(14,19,18,.5)';x.lineWidth=3;for(let i=0;i<=256;i+=64){x.beginPath();x.moveTo(i,0);x.lineTo(i,256);x.stroke();x.beginPath();x.moveTo(0,i);x.lineTo(256,i);x.stroke()}
  const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(3,14);t.colorSpace=THREE.SRGBColorSpace;return t;
}
const concrete=concreteTexture(), floorMap=floorTexture();
const mats={wall:new THREE.MeshStandardMaterial({map:concrete,color:0xb6b2a5,roughness:.92}),floor:new THREE.MeshStandardMaterial({map:floorMap,color:0xb6b6ac,roughness:.9}),dark:new THREE.MeshStandardMaterial({color:0x252c2b,roughness:.76,metalness:.35}),steel:new THREE.MeshStandardMaterial({color:0x59615e,roughness:.42,metalness:.72}),orange:new THREE.MeshStandardMaterial({color:0xd66a20,roughness:.65,metalness:.18}),yellow:new THREE.MeshStandardMaterial({color:0xe3aa38,roughness:.77}),black:new THREE.MeshStandardMaterial({color:0x202323,roughness:.88}),light:new THREE.MeshStandardMaterial({color:0xffe6af,emissive:0xffb34f,emissiveIntensity:2.8}),cyan:new THREE.MeshStandardMaterial({color:0x74c9bc,emissive:0x267d71,emissiveIntensity:1.6})};
const boxGeo=new THREE.BoxGeometry(1,1,1);
function box(parent,mat,x,y,z,sx,sy,sz){const m=new THREE.Mesh(boxGeo,mat);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=false;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,mat,x,y,z,r,len,axis='z'){const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,len,12),mat);m.position.set(x,y,z);if(axis==='x')m.rotation.z=Math.PI/2;if(axis==='z')m.rotation.x=Math.PI/2;parent.add(m);return m}
function stripe(parent,x,y,z,w,h,vertical=false){
  box(parent,mats.black,x,y,z,w,h,.045);
  const count=Math.ceil((vertical?h:w)/.36);
  for(let i=0;i<count;i++){const offset=-((vertical?h:w)/2)+i*.36;const b=box(parent,mats.yellow,x+(vertical?0:offset),y+(vertical?offset:0),z-.03,vertical?.15:.19,vertical?.19:.15,.035);b.rotation.z=vertical?0:-.55}
}
function sign(parent, text, x,y,z, color='#ff9a3e', scale=1){
  const c=document.createElement('canvas');c.width=512;c.height=128;const g=c.getContext('2d');g.fillStyle='rgba(16,23,22,.95)';g.fillRect(0,0,512,128);g.strokeStyle=color;g.lineWidth=5;g.strokeRect(5,5,502,118);g.fillStyle=color;g.font='bold 47px monospace';g.fillText(text,24,81);g.fillStyle='#ddd';g.font='20px monospace';g.fillText('RESEARCH • SUBLEVEL 04',26,111);
  const tx=new THREE.CanvasTexture(c);tx.colorSpace=THREE.SRGBColorSpace;const mesh=new THREE.Mesh(new THREE.PlaneGeometry(2.6*scale,.65*scale),new THREE.MeshBasicMaterial({map:tx,side:THREE.DoubleSide}));mesh.position.set(x,y,z);mesh.rotation.y=x<0?Math.PI/2:-Math.PI/2;parent.add(mesh);
}

// Concrete corridor, repeating structural bays, ceiling raceways, and warning markings.
box(scene,mats.floor,0,-.18,-36,10.6,.36,108);
box(scene,mats.dark,0,6.12,-36,10.6,.5,108);
