box(scene,mats.wall,5.15,2.95,-36,.48,6.2,108);
box(scene,mats.dark,0,2.95,-90,10.6,6.2,.5);
box(scene,mats.dark,0,2.95,18,10.6,6.2,.5);
for(let i=0;i<16;i++){
  const z=13-i*7.1;
  box(scene,mats.dark,-4.88,2.98,z,.1,5.65,.18);box(scene,mats.dark,4.88,2.98,z,.1,5.65,.18);
  box(scene,mats.steel,0,5.94,z,10.25,.17,.22);
  // wall service channels and knee-height protective rub rails
  box(scene,mats.dark,-4.87,4.92,z-3.45,.12,.17,6.7);box(scene,mats.dark,4.87,4.92,z-3.45,.12,.17,6.7);
  box(scene,mats.orange,-4.86,1.02,z-3.45,.09,.16,6.7);box(scene,mats.orange,4.86,1.02,z-3.45,.09,.16,6.7);
  // paired ceiling strips and glowing industrial lamps
  box(scene,mats.dark,-2.5,5.78,z-3.45,.2,.13,5.15);box(scene,mats.dark,2.5,5.78,z-3.45,.2,.13,5.15);
  box(scene,mats.light,0,5.75,z-3.45,1.48,.08,2.05);
  const lamp=new THREE.PointLight(i%3===1?0x9ccbc1:0xffc478,i%3===1?12:16,15,2);lamp.position.set(0,5.25,z-3.45);scene.add(lamp);
  // hazard bands set into the lower walls
