// Wall-mounted steam pipes, brackets, valves, and access panels.
for(let side of [-1,1]){
  for(let p=0;p<4;p++){
    const x=side*(4.48-p*.26), radius=p===0?.12:.07;
    cylinder(scene,p===0?mats.orange:mats.steel,x,4.28,-35,radius,94,'z');
    for(let i=0;i<12;i++)box(scene,mats.dark,x,4.28,12-i*8,.38,.09,.13);
  }
