    box(scene,mats.steel,side*4.77,2.82,z-.02,.13,1.12,1.2);
    box(scene,mats.orange,side*4.68,3.15,z-.64,.035,.15,.035);
    box(scene,mats.cyan,side*4.68,3.15,z-.5,.035,.08,.08);
