box(scene,mats.dark,0,2.6,-89.6,3.2,4.8,.22);box(scene,mats.steel,0,2.6,-89.42,2.85,4.45,.12);
const core=new THREE.Mesh(new THREE.CylinderGeometry(.56,.56,3.7,16),new THREE.MeshStandardMaterial({color:0x986837,emissive:0xe47724,emissiveIntensity:1.2,metalness:.7,roughness:.3}));core.position.set(0,2.5,-89.15);scene.add(core);
const coreLight=new THREE.PointLight(0xff7b26,45,19,2);coreLight.position.set(0,3,-86);scene.add(coreLight);
for(let y=1;y<5;y++)box(scene,mats.orange,0,y,-89.32,2.7,.045,.045);

// Compact pulse carbine, attached to the camera as a diegetic first-person weapon.
const gun=new THREE.Group();camera.add(gun);scene.add(camera);gun.position.set(.32,-.3,-.56);gun.rotation.set(-.04,-.03,.02);
box(gun,mats.dark,0,0,0,.19,.18,.52);box(gun,mats.steel,0,.045,-.11,.22,.11,.25);box(gun,mats.orange,0,-.09,.04,.13,.1,.17);
cylinder(gun,mats.steel,0,.025,-.34,.045,.33,'z');cylinder(gun,mats.orange,0,.025,-.515,.075,.05,'z');
box(gun,mats.cyan,0,.1,-.12,.08,.024,.1);
const muzzle=new THREE.PointLight(0xff822c,0,5,2);muzzle.position.set(0,.02,-.58);gun.add(muzzle);

const raycaster=new THREE.Raycaster();raycaster.far=52;
const enemies=[];let kills=0,health=100,armor=50,started=false,ended=false,fireHeld=false,fireClock=0,damageClock=0,elapsed=0,spawnClock=0;
const healthNum=document.querySelector('#healthNum'),armorNum=document.querySelector('#armorNum'),healthBar=document.querySelector('#healthBar'),armorBar=document.querySelector('#armorBar');
function updateVitals(){healthNum.textContent=health;armorNum.textContent=armor;healthBar.style.width=`${health}%`;armorBar.style.width=`${armor*2}%`}
function makeEnemy(z,x=THREE.MathUtils.randFloat(-2.8,2.8)){
  const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
  const bodyMat=new THREE.MeshStandardMaterial({color:0x394443,roughness:.42,metalness:.52});
  const shell=new THREE.Mesh(new THREE.IcosahedronGeometry(.63,1),bodyMat);shell.position.y=1.48;g.add(shell);
  const armorA=new THREE.Mesh(new THREE.BoxGeometry(.92,.24,.68),mats.dark);armorA.position.set(0,1.47,.05);armorA.rotation.z=.2;g.add(armorA);
  const eye=new THREE.Mesh(new THREE.SphereGeometry(.19,12,10),new THREE.MeshBasicMaterial({color:0xff4c1e}));eye.position.set(0,1.55,-.57);g.add(eye);
  const eyeLight=new THREE.PointLight(0xff421d,1.3,4);eyeLight.position.set(0,1.55,-.68);g.add(eyeLight);
  const horn1=new THREE.Mesh(new THREE.ConeGeometry(.12,.45,8),mats.orange);horn1.position.set(-.43,1.94,.04);horn1.rotation.z=.25;g.add(horn1);
  const horn2=horn1.clone();horn2.position.x=.43;horn2.rotation.z=-.25;g.add(horn2);
  const ring=new THREE.Mesh(new THREE.TorusGeometry(.78,.045,7,24),mats.orange);ring.position.y=1.45;ring.rotation.x=Math.PI/2;g.add(ring);
  const light=new THREE.PointLight(0xff481f,2,6);light.position.y=1.6;g.add(light);
  const enemy={group:g,eye,hp:3,attack:THREE.MathUtils.randFloat(1.7,3),phase:Math.random()*8,speed:THREE.MathUtils.randFloat(.3,.55),alive:true};enemies.push(enemy);return enemy;
}
for(let i=0;i<3;i++)makeEnemy(-11-i*7, (i-1)*1.8);

function fire(){
  if(!started||ended)return;
  muzzle.intensity=8;setTimeout(()=>muzzle.intensity=0,65);
  gun.position.x=.32+THREE.MathUtils.randFloat(-.012,.012);gun.position.y=-.3+THREE.MathUtils.randFloat(-.012,.012);
  raycaster.setFromCamera(new THREE.Vector2(0,0),camera);
  const targets=enemies.filter(e=>e.alive).map(e=>e.group);
  const hit=raycaster.intersectObjects(targets,true)[0];
  if(hit){const e=enemies.find(q=>q.alive&&q.group===hit.object.parent || q.alive&&q.group===hit.object.parent?.parent || q.alive&&q.group===hit.object.parent?.parent?.parent);
    if(e){e.hp--;e.group.scale.setScalar(.94);setTimeout(()=>{if(e.alive)e.group.scale.setScalar(1)},80);const marker=document.querySelector('#hitmarker');marker.classList.add('show');setTimeout(()=>marker.classList.remove('show'),125);if(e.hp<=0){e.alive=false;scene.remove(e.group);kills++;document.querySelector('#threat').textContent=String(Math.max(0,12-kills)).padStart(2,'0');if(kills>=12)finish(true)}}
